import {getV5AdvancedStep} from './v5-advanced-story.mjs';
// Presentation only: the host owns inventory, signatures, acceptance and persistence.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hash=value=>/^[a-f0-9]{64}$/i.test(String(value||''));
const kas=value=>{try{const n=BigInt(value||0),fraction=String(n%100000000n).padStart(8,'0').replace(/0+$/,'');return `${n/100000000n}${fraction?'.'+fraction:''} tKAS`;}catch{return 'Not available';}};
const number=value=>Number(value||0).toLocaleString('en-US',{maximumFractionDigits:1});
const duration=value=>{const n=Math.max(0,Number(value)||0);return n>=3600000?`${number(n/3600000)} hours`:n>=60000?`${Math.ceil(n/60000)} minutes`:`${Math.ceil(n/1000)} seconds`;};
